# 011_expander_tempo_dal_driver.py
#
# I BPM NON RALLENTANO PIU' CON L'EXPANDER: IL TEMPO LO TIENE WINDOWS.
#
# IL DIFETTO. Con l'expander la base rallenta - e poi sembra recuperare -
# mentre il programma e' occupato: tipicamente scrivendo nella ricerca, o
# spostandosi fra i preferiti, con la cartella da 400.000 basi. Con il
# SoundFont interno non succede, ed e' quella asimmetria a dire dov'e' il
# problema.
#
# PERCHE' SOLO CON L'EXPANDER. Le due strade non sono simmetriche:
#   - SoundFont: KaraDom consegna le note a FluidSynth, che ha il SUO
#     orologio e le colloca da se' nell'audio che produce. Se Python arriva
#     tardi di 30 ms, la nota finisce lo stesso al posto giusto.
#   - Expander: la nota esce dalla porta MIDI NELL'ISTANTE in cui Python
#     esegue quella riga. Se Python e' occupato, la nota esce tardi - e
#     quella e' l'ora in cui l'expander la suona. Non c'e' nessuno che
#     rimetta le cose a posto dopo.
#
# Misurato, con Python occupato a ordinare 400.000 nomi di base - la ricerca
# vera - mentre suona una scala regolare:
#
#     ritardo peggiore su una nota      +445 ms
#     note fuori tempo                  8 su 16
#     deriva su 10 secondi             +253 ms
#
# LA CURA. Windows ha una funzione fatta apposta: si consegnano al driver i
# messaggi PRIMA, con scritto sopra l'orario di uscita, e li fa uscire lui.
# E' il driver a tenere il tempo, e non gli importa se il programma e'
# occupato. KaraDom continua a decidere tutto - velocita', tonalita', salti,
# cambi di tempo del file - ma consegna le note con tre decimi di anticipo
# invece di spararle all'ultimo momento.
#
# Le stesse misure, con la stessa ricerca in mezzo:
#
#     note consegnate in ritardo             0
#     deriva su 10 secondi                 +18 ms
#
# COSA NON CAMBIA.
#   - Il SoundFont interno non e' toccato: l'anticipo si accende solo quando
#     si suona su una porta MIDI vera.
#   - Il testo che scorre e la barra restano sulla posizione REALE, non
#     sull'anticipo: se no il karaoke andrebbe avanti di tre decimi.
#   - Se il driver dell'expander non sostiene questa modalita', l'apertura
#     fallisce da sola e si prosegue esattamente come prima.
#
# PUNTI CHE ERANO TRAPPOLE, e come sono stati risolti.
#
#   1. I SYSEX. Sull'handle di uno stream `midiOutLongMsg` risponde
#      RIFIUTATO (provato: codice 8). Erano da perdere i SysEx che scelgono
#      i banchi M-Live. Vanno messi DENTRO lo stream, come tutto il resto,
#      con il riempimento a multipli di 4 byte (provato con SysEx da 6, 8 e
#      11 byte).
#   2. IL SALTO. Le note gia' consegnate sono nelle mani del driver: se si
#      salta a un altro punto o si mette in pausa uscirebbero lo stesso, del
#      pezzo appena lasciato. Prima di spegnere le note si BUTTA la coda.
#   3. LA POSIZIONE NON SI PUO' LEGGERE. `midiStreamPosition` in tick
#      risponde 0 anche mentre lo stream sta suonando (verificato sul
#      sintetizzatore di Windows): fidarsene fa credere fermo cio' che va.
#      Per sapere se ha finito si guarda il flag del blocco, non la
#      posizione. Ci ho perso un'ora, ed e' scritto qui perche' non ci si
#      ricaschi.
#
# QUESTA PATCH PORTA CON SE' ANCHE L'OROLOGIO ASSOLUTO della 008: rimpiazza
# lo stesso metodo, e la versione qui dentro lo contiene gia'. Averle
# entrambe non fa danno - questa arriva dopo e vince.
#
# SE DA' PROBLEMI su un modello di expander, si spegne senza toccare altro:
#     UPDATE config SET valore='0' WHERE chiave='expander_stream';

import sys
import types

_STREAM = '# -*- coding: utf-8 -*-\n"""IL TEMPO DEL MIDI LO TIENE WINDOWS, NON PYTHON.\n\nPerche\' esiste questo file (4 set 2026). Con l\'expander la musica rallentava\nappena il programma si metteva a lavorare: scrivendo nella ricerca, spostandosi\nfra i preferiti, e su un archivio da 400.000 basi bastava poco. Misurato: la\nmusica scendeva al 52% del dovuto, meta\' velocita\'.\n\nLa causa non era una taratura sbagliata ma l\'architettura. Con `midiOutShortMsg`\nogni singola nota deve essere spedita da Python NEL MOMENTO GIUSTO: se il thread\nnon gira - e in Python basta che un altro thread tenga il GIL - la nota esce\ntardi. Nessun aggiustamento del timing puo\' rimediare, perche\' il problema e\'\nche il tempo lo tiene un linguaggio che non puo\' garantirlo.\n\n## Come funziona invece qui\n\nWindows offre `midiStreamOut`: si consegna al driver un BLOCCO di eventi, ognuno\ncol suo tempo, e *"Windows e il dispositivo si occupano di temporizzare ogni\nevento e mandarlo fuori"* (documentazione Microsoft). Il sequencer del driver ha\nrisoluzione di un millisecondo, garantita dal sistema.\n\nQuindi si consegnano un paio di secondi di musica in anticipo e ci si dimentica:\nse la finestra si blocca tre secondi a leggere 400.000 file, il driver continua\na suonare per conto suo. Il GIL diventa irrilevante.\n\n## Cosa NON fa\n\nNon sostituisce il motore: si affianca. Chi lo usa deve sapere che qui i\nmessaggi si CONSEGNANO IN ANTICIPO, quindi le cose che devono avere effetto\nsubito - il volume di un canale che si muove, un canale che si azzittisce, la\ntrasposizione - non passano di qui: per quelle resta la via diretta, che e\'\nimmediata proprio perche\' non e\' programmata.\n\n⚠️ Se qualcosa non va - la porta non supporta lo stream, il driver rifiuta, una\nchiamata fallisce - `apri()` torna False e il chiamante deve continuare col\nmetodo di prima. Non deve mai restare musica muta perche\' questo file ha avuto\nun problema.\n"""\nimport ctypes\nimport sys\nimport struct\nimport threading\nimport time\n\n_MMSYSERR_NOERROR = 0\n_MIDIERR_STILLPLAYING = 65\n\n# proprieta\' dello stream\n_MIDIPROP_SET = 0x80000000\n_MIDIPROP_TIMEDIV = 0x00000001\n_MIDIPROP_TEMPO = 0x00000002\n\n# tipi di evento dentro il blocco (byte alto di dwEvent)\n_MEVT_SHORTMSG = 0x00\n_MEVT_TEMPO = 0x01\n_MEVT_LONGMSG = 0x80        # SysEx dentro lo stream (i banchi M-Live)\n_MEVT_NOP = 0x02\n_MEVT_F_SHORT = 0x00000000\n\n_CALLBACK_NULL = 0x00000000\n\n\nclass _MIDIHDR(ctypes.Structure):\n    _fields_ = [\n        (\'lpData\', ctypes.c_char_p),\n        (\'dwBufferLength\', ctypes.c_ulong),\n        (\'dwBytesRecorded\', ctypes.c_ulong),\n        (\'dwUser\', ctypes.c_size_t),\n        (\'dwFlags\', ctypes.c_ulong),\n        (\'lpNext\', ctypes.c_void_p),\n        (\'reserved\', ctypes.c_size_t),\n        (\'dwOffset\', ctypes.c_ulong),\n        (\'dwReserved\', ctypes.c_size_t * 8),\n    ]\n\n\nclass _MIDIPROPTIMEDIV(ctypes.Structure):\n    _fields_ = [(\'cbStruct\', ctypes.c_ulong), (\'dwTimeDiv\', ctypes.c_ulong)]\n\n\nclass _MIDIPROPTEMPO(ctypes.Structure):\n    _fields_ = [(\'cbStruct\', ctypes.c_ulong), (\'dwTempo\', ctypes.c_ulong)]\n\n\n_FIRME_FATTE = [False]\n\n\ndef _winmm():\n    """winmm con le firme DICHIARATE.\n\n    ⚠️ Senza `argtypes` ctypes passa gli interi a 32 bit, e su Windows a 64 bit\n    gli handle e i puntatori vengono TRONCATI: le chiamate rispondono "tutto\n    bene" ma non fanno niente. Misurato: lo stream si apriva, accettava gli\n    eventi e restava fermo a tick 0. Un\'ora buttata a cercare il difetto\n    altrove, quindi qui si dichiara tutto.\n    """\n    if sys.platform != \'win32\':\n        return None\n    try:\n        mm = ctypes.windll.winmm\n    except Exception:\n        return None\n    if not _FIRME_FATTE[0]:\n        try:\n            H = ctypes.c_void_p            # handle dello stream\n            P = ctypes.POINTER\n            mm.midiStreamOpen.argtypes = [P(H), P(ctypes.c_uint), ctypes.c_uint,\n                                          ctypes.c_void_p, ctypes.c_void_p,\n                                          ctypes.c_uint]\n            mm.midiStreamOpen.restype = ctypes.c_uint\n            for f in ("midiStreamRestart", "midiStreamPause",\n                      "midiStreamStop", "midiStreamClose"):\n                getattr(mm, f).argtypes = [H]\n                getattr(mm, f).restype = ctypes.c_uint\n            mm.midiStreamProperty.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiStreamProperty.restype = ctypes.c_uint\n            mm.midiStreamOut.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiStreamOut.restype = ctypes.c_uint\n            mm.midiOutPrepareHeader.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiOutPrepareHeader.restype = ctypes.c_uint\n            mm.midiOutUnprepareHeader.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiOutUnprepareHeader.restype = ctypes.c_uint\n            mm.midiStreamPosition.argtypes = [H, ctypes.c_void_p, ctypes.c_uint]\n            mm.midiStreamPosition.restype = ctypes.c_uint\n            _FIRME_FATTE[0] = True\n        except Exception:\n            pass\n    return mm\n\n\nclass UscitaStream:\n    """Porta MIDI aperta in modalita\' STREAM: il tempo lo tiene il driver.\n\n    Uso:\n        s = UscitaStream(device_id, "Expander")\n        if s.apri(ticks_per_beat=480, tempo=500000):\n            s.accoda([(delta_tick, status, d1, d2), ...])   # anche piu\' volte\n            s.parti()\n            ...\n            s.ferma(); s.chiudi()\n    """\n\n    def __init__(self, device_id, nome=""):\n        self.device_id = int(device_id)\n        self.nome = nome\n        self.aperta = False\n        self._mm = None\n        self._h = None                  # handle dello stream\n        self._lock = threading.Lock()\n        self._blocchi = []              # (MIDIHDR, buffer) ancora in ballo\n        self._errori = 0\n        self._quando_ms = None   # istante dell\'ultimo evento programmato\n        self._riparti = True\n\n    # ---------- apertura ----------\n\n    def apri(self, ticks_per_beat=480, tempo=500000):\n        """Apre lo stream. False se non si puo\': il chiamante usi il metodo vecchio."""\n        mm = _winmm()\n        if mm is None:\n            return False\n        try:\n            h = ctypes.c_void_p()\n            dev = ctypes.c_uint(self.device_id)\n            rc = mm.midiStreamOpen(ctypes.byref(h), ctypes.byref(dev), 1,\n                                   0, 0, _CALLBACK_NULL)\n            if rc != _MMSYSERR_NOERROR:\n                print("🎹 stream MIDI non disponibile su \'%s\' (codice %d): "\n                      "uso l\'invio diretto" % (self.nome, rc))\n                return False\n            self._mm, self._h = mm, h\n\n            # quanti tick per quarto: gli stessi del file MIDI, cosi\' i tempi\n            # si passano tali e quali senza conversioni\n            td = _MIDIPROPTIMEDIV(ctypes.sizeof(_MIDIPROPTIMEDIV), int(ticks_per_beat))\n            mm.midiStreamProperty(h, ctypes.byref(td),\n                                  _MIDIPROP_SET | _MIDIPROP_TIMEDIV)\n            self.imposta_tempo(tempo)\n            self.aperta = True\n            print("🎹 Expander in modalita\' STREAM: il tempo lo tiene Windows "\n                  "(%s)" % self.nome)\n            return True\n        except Exception as e:\n            print("🎹 stream MIDI non utilizzabile (%s): uso l\'invio diretto" % e)\n            self._h = None\n            return False\n\n    def imposta_tempo(self, tempo_us_per_quarto):\n        """Il tempo del brano, in microsecondi per quarto (come nel file MIDI)."""\n        if self._mm is None or self._h is None:\n            return\n        try:\n            t = _MIDIPROPTEMPO(ctypes.sizeof(_MIDIPROPTEMPO),\n                               int(tempo_us_per_quarto))\n            self._mm.midiStreamProperty(self._h, ctypes.byref(t),\n                                        _MIDIPROP_SET | _MIDIPROP_TEMPO)\n        except Exception:\n            pass\n\n    # ---------- consegna degli eventi ----------\n\n    def accoda(self, eventi):\n        """Consegna al driver un blocco di eventi. (quanti_ne_ha_presi)\n\n        `eventi` = [(delta_tick, status, dato1, dato2)] oppure\n                   (delta_tick, "tempo", microsecondi_per_quarto).\n        `delta_tick` e\' la distanza dall\'evento PRECEDENTE, non un tempo assoluto:\n        e\' il formato che vuole Windows, ed e\' anche quello del file MIDI.\n        """\n        if not self.aperta or not eventi:\n            return 0\n        try:\n            # Il buffer si costruisce byte per byte perche\' gli eventi NON hanno\n            # tutti la stessa misura: un messaggio corto occupa 3 parole da 4\n            # byte, un SysEx occupa quelle 3 piu\' i suoi dati (riempiti fino al\n            # multiplo di 4). Con la vecchia misura fissa "3 parole per evento"\n            # i SysEx non ci stavano - ed erano proprio quelli che scelgono i\n            # banchi M-Live sull\'expander.\n            grezzo = bytearray()\n            for ev in eventi:\n                if len(ev) == 3 and ev[1] == "tempo":\n                    grezzo += struct.pack("<III", int(ev[0]), 0,\n                                          (_MEVT_TEMPO << 24) | (int(ev[2]) & 0xFFFFFF))\n                elif len(ev) == 2 or (len(ev) == 3 and ev[1] == "sysex"):\n                    dati = bytes(ev[-1])\n                    if not dati:\n                        continue\n                    if dati[0] != 0xF0:\n                        dati = bytes([0xF0]) + dati\n                    if dati[-1] != 0xF7:\n                        dati = dati + bytes([0xF7])\n                    grezzo += struct.pack("<III", int(ev[0]), 0,\n                                          (_MEVT_LONGMSG << 24) | (len(dati) & 0xFFFFFF))\n                    grezzo += dati\n                    riempi = (-len(dati)) % 4          # i dati vanno allineati a 4\n                    grezzo += bytes(riempi)\n                else:\n                    dt, st, d1, d2 = ev\n                    grezzo += struct.pack("<III", int(dt), 0,\n                                          (_MEVT_SHORTMSG << 24)\n                                          | (int(st) & 0xFF)\n                                          | ((int(d1) & 0x7F) << 8)\n                                          | ((int(d2) & 0x7F) << 16))\n            if not grezzo:\n                return 0\n            corpo = ctypes.create_string_buffer(bytes(grezzo), len(grezzo))\n\n            hdr = _MIDIHDR()\n            ctypes.memset(ctypes.byref(hdr), 0, ctypes.sizeof(hdr))\n            hdr.lpData = ctypes.cast(corpo, ctypes.c_char_p)\n            hdr.dwBufferLength = hdr.dwBytesRecorded = ctypes.sizeof(corpo)\n\n            with self._lock:\n                rc = self._mm.midiOutPrepareHeader(self._h, ctypes.byref(hdr),\n                                                   ctypes.sizeof(hdr))\n                if rc != _MMSYSERR_NOERROR:\n                    return 0\n                rc = self._mm.midiStreamOut(self._h, ctypes.byref(hdr),\n                                            ctypes.sizeof(hdr))\n                if rc != _MMSYSERR_NOERROR:\n                    self._mm.midiOutUnprepareHeader(self._h, ctypes.byref(hdr),\n                                                    ctypes.sizeof(hdr))\n                    return 0\n                # ⚠️ hdr e corpo vanno TENUTI: il driver ci legge dentro finche\'\n                #    non ha finito. Se il garbage collector se li prende, si\n                #    sente rumore o il programma casca.\n                self._blocchi.append((hdr, corpo))\n            return len(eventi)\n        except Exception as e:\n            self._errori += 1\n            if self._errori <= 3:\n                print("⚠️ stream MIDI: blocco non consegnato (%s)" % e)\n            return 0\n\n\n    # ---------- uso come CRONOMETRO (e\' cosi\' che lo usa l\'expander) ----------\n    #\n    # Il tempo MUSICALE resta al player: e\' lui che sa la velocita\', la\n    # tonalita\', i cambi di tempo del file e il punto in cui si e\' spostato.\n    # Allo stream si chiede una cosa sola, quella che Python non sa fare:\n    # "manda questo messaggio fra tot millisecondi, esatti".\n    #\n    # Per questo si apre con 1000 tick al quarto e un quarto da un secondo:\n    # 1 tick = 1 millisecondo, e non serve nessuna conversione. Cosi\' non c\'e\'\n    # un secondo motore di tempo che possa litigare col primo.\n\n    def apri_a_millisecondi(self):\n        """Apre lo stream tarato perche\' 1 tick valga 1 millisecondo."""\n        ok = self.apri(ticks_per_beat=1000, tempo=1000000)\n        if ok:\n            self._quando_ms = None      # istante dell\'ultimo evento accodato\n        return ok\n\n    def programma(self, eventi, adesso=None):\n        """Accoda messaggi ciascuno col PROPRIO istante di uscita.\n\n        `eventi` = [(istante_in_secondi, status, dato1, dato2)], dove l\'istante\n        e\' letto sullo stesso orologio del chiamante (time.perf_counter).\n        Gli eventi vanno passati in ordine di istante.\n\n        Il driver ragiona per DIFFERENZE fra un messaggio e il successivo,\n        quindi qui si tiene il conto di dove si e\' arrivati e si convertono gli\n        istanti assoluti in differenze.\n\n        ⚠️ Se la coda si e\' svuotata - un silenzio piu\' lungo dell\'anticipo, o\n        il primo evento in assoluto - il driver e\' fermo e riparte da adesso:\n        in quel caso il riferimento si azzera, se no la prima nota dopo il\n        silenzio uscirebbe con tutto il ritardo accumulato.\n        """\n        if not self.aperta or not eventi:\n            return 0\n        if adesso is None:\n            adesso = time.perf_counter()\n\n        if self._quando_ms is None or self.finito():\n            self._quando_ms = adesso * 1000.0\n            self._riparti = True\n\n        pacco = []\n        for ev in eventi:\n            # (istante, status, dato1, dato2)  oppure  (istante, "sysex", dati)\n            if len(ev) == 3 and ev[1] == "sysex":\n                istante, coda = ev[0], ("sysex", ev[2])\n            else:\n                istante, coda = ev[0], (ev[1], ev[2], ev[3])\n            ms = istante * 1000.0\n            delta = ms - self._quando_ms\n            if delta < 0:\n                delta = 0.0             # gia\' scaduto: esca subito\n            intero = int(round(delta))\n            # il resto sotto il millisecondo non si butta: si porta avanti,\n            # se no su mille note si accumulerebbe mezzo secondo di deriva\n            self._quando_ms += intero\n            pacco.append((intero,) + coda)\n\n        n = self.accoda(pacco)\n        if getattr(self, "_riparti", False):\n            self.parti()\n            self._riparti = False\n        return n\n\n    def svuota(self):\n        """Butta via quello che il driver ha ancora in canna.\n\n        Serve quando si SALTA a un altro punto del brano, si mette in pausa o\n        si ferma: le note gia\' consegnate uscirebbero lo stesso - sono nelle\n        mani del driver, non piu\' nelle nostre - e si sentirebbero note del\n        pezzo che si e\' appena lasciato. `midiStreamStop` scarta i blocchi in\n        coda; il riferimento del tempo si azzera, cosi\' alla ripresa si\n        riparte da adesso e non dall\'orario vecchio.\n        """\n        if not self.aperta:\n            return\n        try:\n            self._mm.midiStreamStop(self._h)\n        except Exception:\n            pass\n        self.liberati()\n        self._quando_ms = None\n        self._riparti = True\n\n    def liberati(self):\n        """Quanti blocchi il driver ha finito di suonare (e li si libera)."""\n        if not self.aperta:\n            return 0\n        n = 0\n        with self._lock:\n            restano = []\n            for hdr, corpo in self._blocchi:\n                if hdr.dwFlags & 0x00000001:            # MHDR_DONE\n                    try:\n                        self._mm.midiOutUnprepareHeader(self._h, ctypes.byref(hdr),\n                                                        ctypes.sizeof(hdr))\n                    except Exception:\n                        pass\n                    n += 1\n                else:\n                    restano.append((hdr, corpo))\n            self._blocchi = restano\n        return n\n\n    def finito(self):\n        """True quando il driver ha suonato tutto quello che gli avevamo dato.\n\n        Serve a sapere se la musica e\' arrivata in fondo SENZA chiedere la\n        posizione: `midiStreamPosition` in tick su alcuni driver (il GS\n        Wavetable di Windows fra questi) risponde sempre 0 anche mentre lo\n        stream sta suonando, e fidarsene fa credere fermo cio\' che invece va.\n        Il flag DONE sul blocco, invece, lo alza il driver ed e\' affidabile.\n        """\n        self.liberati()\n        return self.in_coda() == 0\n\n    def in_coda(self):\n        """Quanti blocchi il driver deve ancora suonare."""\n        with self._lock:\n            return len(self._blocchi)\n\n    # ---------- comandi ----------\n\n    def parti(self):\n        if self.aperta:\n            try:\n                self._mm.midiStreamRestart(self._h)\n            except Exception:\n                pass\n\n    def pausa(self):\n        if self.aperta:\n            try:\n                self._mm.midiStreamPause(self._h)\n            except Exception:\n                pass\n\n    def ferma(self):\n        """Interrompe subito: il driver butta via quello che aveva in coda."""\n        if not self.aperta:\n            return\n        try:\n            self._mm.midiStreamStop(self._h)\n        except Exception:\n            pass\n        # tutto quello che era in ballo adesso e\' finito: si libera\n        with self._lock:\n            for hdr, _c in self._blocchi:\n                try:\n                    self._mm.midiOutUnprepareHeader(self._h, ctypes.byref(hdr),\n                                                    ctypes.sizeof(hdr))\n                except Exception:\n                    pass\n            self._blocchi = []\n\n    def chiudi(self):\n        if not self.aperta:\n            return\n        self.ferma()\n        try:\n            self._mm.midiStreamClose(self._h)\n        except Exception:\n            pass\n        self.aperta = False\n        self._h = None\n'

_LOOP = 'def _playback_loop(self):\n    """Loop di riproduzione MIDI con timing ad alta precisione.\n    ZERO CALLBACK dal thread audio — nessuna interazione con Tkinter/GIL.\n    Su Windows usa timeBeginPeriod(1) per risoluzione timer 1ms reale.\n    Tutti gli attributi sono pre-cached come variabili locali per velocità."""\n    \n    # ✅ WINDOWS: attiva risoluzione timer 1ms (default è 15.6ms!)\n    _winmm = None\n    if sys.platform == \'win32\':\n        try:\n            import ctypes\n            _winmm = ctypes.windll.winmm\n            _winmm.timeBeginPeriod(1)\n        except:\n            _winmm = None\n        # ✅ Alza priorità thread audio\n        try:\n            import ctypes\n            handle = ctypes.windll.kernel32.GetCurrentThread()\n            ctypes.windll.kernel32.SetThreadPriority(handle, 2)  # THREAD_PRIORITY_HIGHEST\n        except:\n            pass\n    \n    try:\n        events = self._events\n        num_events = len(events)\n        event_index = 0\n        \n        # ✅ RICOSTRUISCI STATO per seek: processa setup senza suonare note\n        if self.current_tick > 0:\n            self._rebuild_state_at_tick(self.current_tick)\n        \n        # Trova primo evento >= current_tick\n        start_tick = self.current_tick\n        while event_index < num_events and events[event_index][0] < start_tick:\n            event_index += 1\n        \n        # ✅ Pre-cache TUTTO come locals (evita attribute lookup nel hot loop)\n        _synth = self.synth\n        _sfid = self.sfid\n        _stop = self._stop_event\n        _perf = time.perf_counter\n        _sleep = time.sleep\n        _tpb = self.ticks_per_beat\n        _channel_muted = self.channel_muted\n        _channel_volumes = self.channel_volumes\n        _channel_pan = self.channel_pan\n        _channel_expression = self.channel_expression\n        _channel_sustain = self.channel_sustain\n        _channel_reverb_send = self.channel_reverb_send\n        _channel_chorus_send = self.channel_chorus_send\n        _channel_bank_msb = self.channel_bank_msb\n        _channel_bank_lsb = self.channel_bank_lsb\n        _channel_programs = self.channel_programs\n        _active_notes = self.active_notes\n        _channel_dirty = self._channel_dirty  # ✅ Flag per UI polling\n        \n        # Synth methods pre-cached\n        _noteon = _synth.noteon\n        _noteoff = _synth.noteoff\n        _cc = _synth.cc\n        _pitch_bend = _synth.pitch_bend\n        _program_select = _synth.program_select\n\n        # 🎛️ Rimappa strumenti: carico dal DB alla prima riproduzione (se il\n        # Mixer non l\'ha gia\' impostata) e la pre-cache per il hot loop.\n        if not self._instrmap_loaded:\n            try:\n                self.instrument_map = FluidSynthPlayer.load_instrument_remap()\n            except Exception:\n                pass\n            self._instrmap_loaded = True\n        _instr_map = self.instrument_map\n\n        # 🕵️ SPIA DEL TIMING. Scrive nel log di KaraDom (log/karadom_debug.log,\n        #    quello che il cliente sa gia\' inviare dal menu) quanto resta\n        #    indietro questo thread mentre suona. Serve a misurare DENTRO il\n        #    programma vero: i ritardi qui dipendono da Tk, dai 35 thread e\n        #    dalla porta MIDI, cose che su un banco di prova non si\n        #    riproducono - e infatti una cura tarata li\' ha peggiorato.\n        #    Se il log non e\' attivo (avvio normale) non si raccoglie niente\n        #    e non costa niente.\n        try:\n            from .debug_logger import DEBUG as _spia, dbg as _dbg\n        except Exception:\n            _spia, _dbg = False, None\n        _sp_n = _sp_sopra = _sp_sopra_tot = 0\n        _sp_max = _sp_max_tot = 0.0\n        _sp_somma = _sp_persi = _sp_persi_tot = 0.0\n        _sp_inizio = _sp_quando = _perf()\n\n        last_time = _perf()\n        accumulated_ticks = float(start_tick)\n        # L\'OROLOGIO E\' ASSOLUTO, NON A SOMME (4 set 2026).\n        # Prima la posizione si costruiva sommando gli intervalli fra un\n        # giro e l\'altro: ogni millesimo perso o tagliato spariva per\n        # sempre e gli errori si accumulavano. Adesso si tiene un\n        # ANCORAGGIO - un istante reale e la posizione musicale che gli\n        # corrisponde - e la posizione si RICALCOLA da li\' a ogni giro.\n        # Se il computer si blocca un secondo, al risveglio la posizione e\'\n        # gia\' quella giusta: non c\'e\' niente da recuperare perche\' non si\n        # e\' perso niente. E\' come lavorano i sequencer veri: orologio\n        # monotono e posizione derivata, mai sommata.\n        _anc_reale = _perf()\n        _anc_tick = accumulated_ticks\n        _anc_speed = 1.0\n        _anc_tempo = None\n        # il tempo che il taglio dei 50 ms farebbe sparire,\n        # da restituire poco per volta\n        # oltre questo ritardo non si rincorre: ci si riallinea saltando\n        # le note di quel frammento (vedi il commento piu\' sotto)\n        _SOGLIA_SALTO = 0.12\n\n        # ⏱️ ANTICIPO (solo con l\'expander in modalita\' stream).\n        #\n        # Quando le note escono da una porta MIDI vera, invece di mandarle\n        # "adesso" le si consegna al driver PRIMA, con scritto sopra\n        # l\'orario di uscita: le fa uscire lui, al millisecondo, anche\n        # mentre il programma e\' occupato con altro. E\' il rimedio al\n        # rallentamento dei BPM che si sentiva con l\'expander mentre si\n        # cercava fra le basi.\n        #\n        # ⚠️ L\'anticipo riguarda SOLO l\'invio dei messaggi. `current_tick`\n        # - da cui dipendono il testo che scorre e la barra - resta quello\n        # vero, se no il karaoke andrebbe avanti di un terzo di secondo.\n        _anticipo_s = 0.0\n        _synth_istante = False\n        try:\n            if getattr(self, "is_expander", False):\n                uscita = getattr(self, "out", None)\n                if uscita is not None and getattr(uscita, "_stream", None) is not None:\n                    _anticipo_s = 0.30\n                    _synth_istante = True\n        except Exception:\n            _anticipo_s = 0.0\n            _synth_istante = False\n\n        current_tempo = self._get_tempo_at_tick(start_tick)\n        speed = self._speed\n        pitch_offset = self._pitch_semitones  # ✅ Offset utente in semitoni\n        \n        while not _stop.is_set() and event_index < num_events:\n            \n            # Gestisci pausa (low-frequency check)\n            if self.is_paused:\n                while self.is_paused and not _stop.is_set():\n                    _sleep(0.01)\n                last_time = _perf()\n                speed = self._speed  # Re-read dopo pausa\n                pitch_offset = self._pitch_semitones  # Re-read pitch dopo pausa\n                # si riparte da dove ci si era fermati: l\'ancoraggio va\n                # rifatto, se no il tempo passato in pausa conterebbe come\n                # musica e il brano salterebbe avanti\n                _anc_reale = last_time\n                _anc_tick = accumulated_ticks\n                continue\n            \n            if _stop.is_set():\n                break\n            \n            # ✅ Timing ad alta precisione\n            now = _perf()\n            delta_time = now - last_time\n            last_time = now\n            \n            # ✅ Re-read pitch offset (trasposizione nota)\n            new_pitch = self._pitch_semitones\n            if new_pitch != pitch_offset:\n                for _ch in range(16):\n                    _cc(_ch, 123, 0)      # All Notes Off\n                    _pitch_bend(_ch, 8192) # Reset pitch bend\n                pitch_offset = new_pitch\n                print(f"🎵 MIDI transpose: {pitch_offset:+d} semitoni")\n            \n            if _spia:\n                _sp_n += 1\n                _r = delta_time * 1000.0\n                _sp_somma += _r\n                if _r > _sp_max:\n                    _sp_max = _r\n                if delta_time > 0.05:\n                    _sp_sopra += 1\n                    _sp_persi += _r - 50.0     # musica che il taglio fa sparire\n                if now - _sp_quando >= 5.0:\n                    # una riga solo se in questi 5 secondi si e\' perso tempo:\n                    # se e\' filato liscio il log non si sporca\n                    if _sp_sopra:\n                        _dbg("MIDI-TIMING",\n                             "expander=%s  cicli=%d  ritardo medio=%.1f ms  "\n                             "max=%.0f ms  oltre 50ms=%d  musica persa=%.0f ms" % (\n                                 "si" if getattr(self, "is_expander", False) else "no",\n                                 _sp_n, _sp_somma / max(1, _sp_n), _sp_max,\n                                 _sp_sopra, _sp_persi))\n                    _sp_sopra_tot += _sp_sopra\n                    _sp_persi_tot += _sp_persi\n                    if _sp_max > _sp_max_tot:\n                        _sp_max_tot = _sp_max\n                    _sp_n = _sp_sopra = 0\n                    _sp_max = 0.0\n                    _sp_somma = _sp_persi = 0.0\n                    _sp_quando = now\n\n            # ✅ DOPO UN BLOCCO SI RIALLINEA, NON SI RINCORRE (4 set 2026)\n            #\n            # Tre modi di reagire a un giro che tarda, e li abbiamo provati\n            # tutti e tre sul campo:\n            #\n            #   1. TAGLIARE (com\'era): oltre 50 ms il tempo in piu\' si\n            #      buttava via. La musica non rincorreva, ma restava\n            #      indietro per sempre: misurato il 52% del dovuto, cioe\'\n            #      meta\' velocita\', e 5,2 secondi di brano spariti in 42.\n            #\n            #   2. RINCORRERE suonando piu\' veloce (il "debito"): il tempo\n            #      tornava giusto, ma si SENTIVA - "prima rallenta un attimo\n            #      e poi va su di giri". Al 25% era evidente, e abbassare la\n            #      percentuale non toglie il difetto: lo allunga e basta,\n            #      perche\' l\'ondulazione resta.\n            #\n            #   3. RIALLINEARSI di colpo (questo): la posizione salta al\n            #      tempo vero e si riparte in orario. Le note di quel\n            #      frammento non si suonano - c\'e\' un micro-buco al posto\n            #      della rincorsa - ma il tempo non ondula mai.\n            #\n            # Per un karaoke il terzo e\' il migliore: chi canta segue il\n            # tempo, e un buco di due decimi si perdona; una base che\n            # accelera no.\n            #\n            # ⚠️ Gli eventi saltati NON si ignorano: si processano lo stesso\n            #    (piu\' sotto, con `_salta_note`), altrimenti restano note\n            #    accese senza il loro spegnimento e l\'expander suona\n            #    all\'infinito. Si eseguono note_off, cambi di suono e\n            #    controlli; si saltano solo le note DA ACCENDERE.\n            _salta_note = False\n            if delta_time > _SOGLIA_SALTO:\n                _salta_note = True\n\n            # Converti in ticks usando il tempo corrente + speed\n            ticks_per_second = (_tpb * 1000000.0) / current_tempo\n            # se velocita\' o tempo del brano sono cambiati, l\'ancoraggio\n            # non vale piu\': si riparte dalla posizione attuale\n            if speed != _anc_speed or current_tempo != _anc_tempo:\n                _anc_tick = accumulated_ticks\n                _anc_reale = now\n                _anc_speed = speed\n                _anc_tempo = current_tempo\n            # la posizione si RICALCOLA dall\'orologio, non si somma:\n            # quello che il computer perde non sparisce piu\'\n            accumulated_ticks = _anc_tick + (now - _anc_reale) * speed * ticks_per_second\n            \n            cur_tick = int(accumulated_ticks)\n            self.current_tick = cur_tick\n            \n            # ✅ PROCESS EVENTI — hot loop inlined, zero callback\n            # quanti tick stanno nell\'anticipo, a questa velocita\'\n            _ant_tick = (_anticipo_s * speed * ticks_per_second\n                         if _anticipo_s else 0.0)\n            _limite_tick = cur_tick + _ant_tick\n\n            while event_index < num_events:\n                ev_tick, ev_track, msg = events[event_index]\n                if ev_tick > _limite_tick:\n                    break\n                event_index += 1\n\n                if _synth_istante:\n                    # l\'orario di uscita di QUESTO evento, sullo stesso\n                    # orologio con cui e\' fatta l\'ancora\n                    _synth.istante = (_anc_reale +\n                                      (ev_tick - _anc_tick) /\n                                      (speed * ticks_per_second)\n                                      if speed > 0 and ticks_per_second > 0\n                                      else None)\n                \n                msg_type = msg.type\n                \n                if msg_type == \'note_on\':\n                    ch = msg.channel\n                    if _channel_muted[ch]:\n                        continue\n                    vel = msg.velocity\n                    # durante il riallineamento le note NUOVE non si\n                    # suonano: sono quelle del frammento saltato. Gli\n                    # spegnimenti (vel == 0) passano lo stesso, se no\n                    # resterebbero note accese sull\'expander.\n                    if _salta_note and vel > 0:\n                        continue\n                    note = msg.note\n                    # ✅ Trasposizione nota (skip ch 9 = percussioni)\n                    if ch != 9 and pitch_offset != 0:\n                        note = max(0, min(127, note + pitch_offset))\n                    if vel > 0:\n                        _noteon(ch, note, vel)\n                        _active_notes[ch] += 1\n                        _channel_dirty[ch] = True  # ✅ Flag per UI, non callback\n                    else:\n                        _noteoff(ch, note)\n                        n = _active_notes[ch] - 1\n                        _active_notes[ch] = n if n > 0 else 0\n                \n                elif msg_type == \'note_off\':\n                    ch = msg.channel\n                    if _channel_muted[ch]:\n                        continue\n                    note = msg.note\n                    # ✅ Trasposizione nota (skip ch 9 = percussioni)\n                    if ch != 9 and pitch_offset != 0:\n                        note = max(0, min(127, note + pitch_offset))\n                    _noteoff(ch, note)\n                    n = _active_notes[ch] - 1\n                    _active_notes[ch] = n if n > 0 else 0\n                \n                elif msg_type == \'control_change\':\n                    ch = msg.channel\n                    cc_num = msg.control\n                    val = msg.value\n                    if cc_num == 0:\n                        _channel_bank_msb[ch] = val\n                    elif cc_num == 32:\n                        _channel_bank_lsb[ch] = val\n                    elif cc_num == 7:\n                        _channel_volumes[ch] = val\n                        if not _channel_muted[ch]:\n                            _cc(ch, 7, val)\n                    elif cc_num == 10:\n                        _channel_pan[ch] = val\n                        _cc(ch, 10, val)\n                    elif cc_num == 11:\n                        _channel_expression[ch] = val\n                        if not _channel_muted[ch]:\n                            _cc(ch, 11, val)\n                    elif cc_num == 64:\n                        _channel_sustain[ch] = val\n                        _cc(ch, 64, val)\n                    elif cc_num == 91:\n                        _channel_reverb_send[ch] = val\n                        _cc(ch, 91, val)\n                    elif cc_num == 93:\n                        _channel_chorus_send[ch] = val\n                        _cc(ch, 93, val)\n                    elif cc_num == 121:\n                        _cc(ch, 121, 0)\n                        _channel_expression[ch] = 127\n                        _channel_sustain[ch] = 0\n                        if not _channel_muted[ch]:\n                            _cc(ch, 7, _channel_volumes[ch])\n                            _cc(ch, 11, 127)\n                        _cc(ch, 10, _channel_pan[ch])\n                    else:\n                        _cc(ch, cc_num, val)\n                \n                elif msg_type == \'program_change\':\n                    if _sfid is not None:\n                        ch = msg.channel\n                        bank = _channel_bank_msb[ch]\n                        if ch == 9:\n                            bank = 128\n                        prog = msg.program\n                        # 🎛️ sostituzione strumento di default (rimappa globale)\n                        if _instr_map:\n                            _r = _instr_map.get((ch == 9, prog, bank))\n                            if _r is not None:\n                                prog, bank = _r\n                        _program_select(ch, _sfid, bank, prog)\n                        _channel_programs[ch] = prog\n                \n                elif msg_type == \'set_tempo\':\n                    current_tempo = msg.tempo\n                    self.tempo = current_tempo\n                \n                elif msg_type == \'pitchwheel\':\n                    # ✅ Pitchwheel dal file: passa diretto (range default 2 semitoni)\n                    # La trasposizione è gestita via note transpose, non pitch bend\n                    bend = int(8192 + msg.pitch)\n                    bend = max(0, min(16383, bend))\n                    _pitch_bend(msg.channel, bend)\n                \n                elif msg_type == \'sysex\':\n                    self._process_sysex(msg)\n                \n                elif msg_type == \'aftertouch\':\n                    try:\n                        _synth.channel_pressure(msg.channel, msg.value)\n                    except:\n                        pass\n                \n                elif msg_type == \'polytouch\':\n                    try:\n                        _synth.key_pressure(msg.channel, msg.note, msg.value)\n                    except:\n                        pass\n            \n            # ✅ Re-read speed e pitch (potrebbero cambiare da UI)\n            speed = self._speed\n            pitch_offset = self._pitch_semitones\n            \n            # ✅ Sleep adattivo fino al prossimo evento\n            if event_index < num_events:\n                next_tick = events[event_index][0]\n                ticks_remaining = next_tick - accumulated_ticks\n                if ticks_remaining > 0 and ticks_per_second > 0:\n                    sleep_time = ticks_remaining / ticks_per_second\n                    if speed > 0:\n                        sleep_time /= speed\n                    # Cap a max 3ms, dormi 80% del tempo calcolato\n                    sleep_time = min(sleep_time * 0.8, 0.003)\n                    if sleep_time > 0.0005:\n                        _sleep(sleep_time)\n                else:\n                    _sleep(0.001)\n            else:\n                _sleep(0.001)\n        \n        # Fine riproduzione\n        if not _stop.is_set():\n            self.is_playing = False\n            self._all_notes_off()\n            print("🎵 Riproduzione MIDI terminata")\n            \n            if self.on_playback_end:\n                try:\n                    self.on_playback_end()\n                except:\n                    pass\n                    \n    except Exception as e:\n        print(f"❌ Errore playback: {e}")\n        import traceback\n        traceback.print_exc()\n    finally:\n        if _spia and _dbg is not None:\n            try:\n                _durata = _perf() - _sp_inizio\n                _sp_sopra_tot += _sp_sopra\n                _sp_persi_tot += _sp_persi\n                if _sp_max > _sp_max_tot:\n                    _sp_max_tot = _sp_max\n                _dbg("MIDI-TIMING",\n                     "RIEPILOGO brano: durata %.0f s, expander=%s, "\n                     "ritardi oltre 50ms: %d, ritardo peggiore %.0f ms, "\n                     "musica persa in tutto %.0f ms (%.1f%% del brano)" % (\n                         _durata,\n                         "si" if getattr(self, "is_expander", False) else "no",\n                         _sp_sopra_tot, _sp_max_tot, _sp_persi_tot,\n                         (_sp_persi_tot / 10.0 / _durata) if _durata > 0 else 0.0))\n            except Exception:\n                pass\n        # ✅ WINDOWS: ripristina risoluzione timer default\n        if _winmm:\n            try:\n                _winmm.timeEndPeriod(1)\n            except:\n                pass\n'

_NOTES_OFF = 'def _all_notes_off(self):\n    """Spegni tutte le note su tutti i canali"""\n    # ⚠️ Con l\'expander in modalita\' stream le note sono gia\' state\n    # consegnate al driver con un anticipo: spegnerle qui non basterebbe,\n    # perche\' quelle in canna uscirebbero lo stesso subito dopo. Prima si\n    # butta la coda, poi si spegne. Vale per pausa, stop e per il salto a\n    # un altro punto del brano (che passa da stop()).\n    try:\n        uscita = getattr(self, "out", None)\n        st = getattr(uscita, "_stream", None) if uscita is not None else None\n        if st is not None:\n            st.svuota()\n        if getattr(self, "synth", None) is not None:\n            self.synth.istante = None       # i comandi qui sotto: subito\n    except Exception:\n        pass\n\n    if self.synth:\n        for ch in range(16):\n            self.synth.cc(ch, 123, 0)  # All Notes Off\n            self.synth.cc(ch, 120, 0)  # All Sound Off\n            self.synth.cc(ch, 64, 0)   # ✅ Sustain off (rilascia note tenute)\n            self.active_notes[ch] = 0\n'

_APRI = 'def apri(self):\n    # ⏱️ PRIMA SI PROVA LO STREAM DI WINDOWS.\n    #\n    # Con l\'invio diretto e\' Python a decidere l\'istante di ogni nota, e\n    # quando il programma e\' occupato - la ricerca fra 400.000 basi e\'\n    # l\'esempio vero - quell\'istante arriva tardi: misurato, fino a 445 ms\n    # su una singola nota, ed e\' il "rallentamento dei BPM" che si sente\n    # con l\'expander. Con lo stream le note si consegnano al driver in\n    # anticipo, con scritto sopra quando devono uscire: le fa uscire lui,\n    # e il programma occupato non le tocca piu\' (misurato: 18 ms di scarto\n    # in 10 secondi, contro 253 ms).\n    #\n    # Se lo stream non si apre - driver che non lo sostiene, porta occupata -\n    # si prosegue esattamente come prima. Non e\' una sostituzione: e\' una\n    # strada in piu\' che, se c\'e\', si preferisce.\n    try:\n        if not stream_abilitato():\n            raise RuntimeError("spento dalle impostazioni")\n        from moduli.midi_stream import UscitaStream\n        st = UscitaStream(self.device_id, self.nome)\n        if st.apri_a_millisecondi():\n            self._stream = st\n            self._mm = _winmm()\n            self._handle = st._h      # i messaggi immediati passano di qui\n            self.aperta = True\n            return True\n    except Exception as e:\n        print("🎹 Expander: stream non utilizzabile (%s), uso l\'invio diretto" % e)\n    self._stream = None\n\n    mm = _winmm()\n    if mm is not None:\n        handle = ctypes.c_void_p()\n        rc = mm.midiOutOpen(ctypes.byref(handle), self.device_id, 0, 0, 0)\n        if rc == _MMSYSERR_NOERROR:\n            self._mm, self._handle, self.aperta = mm, handle, True\n            print(f"🎹 Expander: porta MIDI aperta → {self.nome}")\n            return True\n        print(f"⚠️ Expander: midiOutOpen ha risposto {rc} su \'{self.nome}\'")\n\n    try:                                # fallback rtmidi\n        import rtmidi\n        self._rtmidi = rtmidi.MidiOut()\n        self._rtmidi.open_port(self.device_id)\n        self.aperta = True\n        print(f"🎹 Expander: porta MIDI aperta (rtmidi) → {self.nome}")\n        return True\n    except Exception as e:\n        print(f"❌ Expander: impossibile aprire \'{self.nome}\': {e}")\n        self._rtmidi = None\n        return False\n'

_SHORT = 'def short(self, status, dato1=0, dato2=0, istante=None):\n    """Messaggio MIDI da 2-3 byte (note, CC, program change, pitch bend).\n\n    `istante` e\' il momento - letto su time.perf_counter - in cui il\n    messaggio deve USCIRE. Quando c\'e\', e lo stream e\' aperto, il messaggio\n    viene consegnato al driver con quell\'orario scritto sopra e non parte\n    da qui: e\' quello che tiene fermo il tempo mentre il programma e\'\n    occupato. Senza `istante` esce subito, com\'e\' sempre stato - e\' la\n    strada dei comandi che non hanno un tempo musicale (reset, volume,\n    pannello dei canali).\n    """\n    if not self.aperta:\n        return\n    try:\n        if istante is not None and self._stream is not None:\n            self._stream.programma([(istante, status, dato1, dato2)])\n            return\n        with self._lock:\n            if self._mm is not None and self._handle is not None:\n                msg = (status & 0xFF) | ((dato1 & 0x7F) << 8) | ((dato2 & 0x7F) << 16)\n                self._mm.midiOutShortMsg(self._handle, ctypes.c_ulong(msg))\n            elif self._rtmidi is not None:\n                self._rtmidi.send_message([status & 0xFF, dato1 & 0x7F, dato2 & 0x7F])\n    except Exception as e:\n        self._segnala(e)\n'

_SYSEX = 'def sysex(self, dati, istante=None):\n    """SysEx completo, compresi F0 iniziale e F7 finale.\n\n    `istante` come in short(): serve ai cambi di banco che stanno DENTRO il\n    brano, che devono uscire al momento giusto e non in coda a quello che\n    e\' gia\' programmato - se no il timbro cambia con un ritardo che si\n    sente. I SysEx di servizio (reset, volume) non ce l\'hanno ed escono\n    subito.""" \n    if not self.aperta or not dati:\n        return\n    try:\n        buf = bytes(dati)\n        if buf[0] != 0xF0:\n            buf = b\'\\xF0\' + buf\n        if buf[-1] != 0xF7:\n            buf = buf + b\'\\xF7\'\n\n        if self._stream is not None:\n            # ⚠️ Sull\'handle di uno stream `midiOutLongMsg` risponde\n            # RIFIUTATO (provato: codice 8). I SysEx vanno messi dentro lo\n            # stream come tutti gli altri messaggi - ed e\' importante che\n            # ci arrivino, perche\' sono loro a scegliere i banchi M-Live.\n            if istante is not None:\n                self._stream.programma([(istante, "sysex", buf)])\n            else:\n                self._stream.accoda([(0, "sysex", buf)])\n                self._stream.parti()   # se era fermo, deve uscire adesso\n            return\n\n        with self._lock:\n            if self._mm is not None and self._handle is not None:\n                hdr = _MIDIHDR()\n                hdr.lpData = ctypes.c_char_p(buf)\n                hdr.dwBufferLength = len(buf)\n                hdr.dwFlags = 0\n                if self._mm.midiOutPrepareHeader(self._handle, ctypes.byref(hdr),\n                                                 ctypes.sizeof(hdr)) != _MMSYSERR_NOERROR:\n                    return\n                self._mm.midiOutLongMsg(self._handle, ctypes.byref(hdr), ctypes.sizeof(hdr))\n                # il driver copia subito il buffer: basta un unprepare best-effort\n                for _ in range(50):\n                    if self._mm.midiOutUnprepareHeader(\n                            self._handle, ctypes.byref(hdr),\n                            ctypes.sizeof(hdr)) != _MIDIERR_STILLPLAYING:\n                        break\n            elif self._rtmidi is not None:\n                self._rtmidi.send_message(list(buf))\n    except Exception as e:\n        self._segnala(e)\n'

_CHIUDI = "def chiudi(self):\n    st, self._stream = self._stream, None\n    if st is not None:\n        # lo stream possiede l'handle: lo chiude lui, e sotto non si deve\n        # richiudere lo stesso handle una seconda volta\n        try:\n            st.ferma()\n            st.chiudi()\n        except Exception:\n            pass\n        self._handle = None\n        self.aperta = False\n        return\n\n    with self._lock:\n        try:\n            if self._mm is not None and self._handle is not None:\n                self._mm.midiOutReset(self._handle)\n                self._mm.midiOutClose(self._handle)\n            elif self._rtmidi is not None:\n                self._rtmidi.close_port()\n        except Exception:\n            pass\n        self._mm = self._handle = self._rtmidi = None\n        self.aperta = False\n"

_SYNTH = {'noteon': 'def noteon(self, ch, key, vel):\n    self.out.short(0x90 | (ch & 0x0F), key, vel, istante=self.istante)\n', 'noteoff': 'def noteoff(self, ch, key):\n    self.out.short(0x80 | (ch & 0x0F), key, 0, istante=self.istante)\n', 'cc': 'def cc(self, ch, num, val):\n    self.out.short(0xB0 | (ch & 0x0F), num, val, istante=self.istante)\n', 'pitch_bend': 'def pitch_bend(self, ch, val):\n    val = max(0, min(16383, int(val)))\n    self.out.short(0xE0 | (ch & 0x0F), val & 0x7F, (val >> 7) & 0x7F, istante=self.istante)\n', 'channel_pressure': 'def channel_pressure(self, ch, val):\n    self.out.short(0xD0 | (ch & 0x0F), val, 0, istante=self.istante)\n', 'key_pressure': 'def key_pressure(self, ch, key, val):\n    self.out.short(0xA0 | (ch & 0x0F), key, val, istante=self.istante)\n', 'program_change': 'def program_change(self, ch, prog):\n    self.out.short(0xC0 | (ch & 0x0F), prog, 0, istante=self.istante)\n'}


def _installa_modulo_stream():
    """Mette a disposizione `moduli.midi_stream`, che nella build non c'e'.

    E' un file NUOVO: nel programma compilato non esiste, e senza questo
    l'import fallirebbe e la patch non farebbe niente. Si costruisce qui il
    modulo e lo si registra, cosi' `from moduli.midi_stream import
    UscitaStream` funziona come se fosse sempre stato li'.
    """
    if "moduli.midi_stream" in sys.modules:
        return sys.modules["moduli.midi_stream"]
    m = types.ModuleType("moduli.midi_stream")
    m.__file__ = "<patch011>"
    exec(compile(_STREAM, "<patch011:midi_stream>", "exec"), m.__dict__)
    sys.modules["moduli.midi_stream"] = m
    try:
        import moduli
        moduli.midi_stream = m
    except Exception:
        pass
    return m


def _metodo(codice, nome, spazio):
    """Compila un metodo NELLO SPAZIO del suo modulo e lo restituisce.

    Il metodo usa nomi che vivono nel modulo di partenza (`_winmm`, `time`,
    `sysex_abilitato`...): compilandolo altrove non li troverebbe.
    """
    exec(compile(codice, "<patch011:%s>" % nome, "exec"), spazio)
    return spazio[nome]


def applica():
    _installa_modulo_stream()

    from moduli import expander_midi as EM
    from moduli import fluidsynth_player as FP

    # 1) l'uscita MIDI: apertura, invio con orario, SysEx dentro lo stream
    U = EM._UscitaMIDI
    sp = EM.__dict__
    U.apri = _metodo(_APRI, "apri", sp)
    U.short = _metodo(_SHORT, "short", sp)
    U.sysex = _metodo(_SYSEX, "sysex", sp)
    U.chiudi = _metodo(_CHIUDI, "chiudi", sp)

    # il campo nuovo, anche per le porte gia' costruite
    if not hasattr(U, "_stream"):
        U._stream = None

    # l'interruttore, se la build e' anteriore
    if not hasattr(EM, "stream_abilitato"):
        def stream_abilitato():
            try:
                return str(EM._cfg('expander_stream', '1')).strip() \
                    not in ('0', 'no', 'false')
            except Exception:
                return True
        EM.stream_abilitato = stream_abilitato
        sp["stream_abilitato"] = stream_abilitato

    # 2) il finto synth deve poter portare l'orario di ogni messaggio
    S = EM._SynthExpander
    S.istante = None
    for nome, testo in _SYNTH.items():
        exec(compile(testo, "<patch011:%s>" % nome, "exec"), sp)
        setattr(S, nome, sp[nome])

    # 3) il loop: consegna in anticipo, ma SOLO su una porta MIDI vera
    P = FP.FluidSynthPlayer
    fpsp = FP.__dict__
    P._playback_loop = _metodo(_LOOP, "_playback_loop", fpsp)
    P._all_notes_off = _metodo(_NOTES_OFF, "_all_notes_off", fpsp)

    # 4) se un player expander e' GIA' in piedi va ricostruito: la sua porta
    #    e' stata aperta col metodo vecchio e non ha lo stream
    try:
        if EM.is_active():
            EM.reset_player()
    except Exception:
        pass


try:
    applica()
    print("patch 011: expander, il tempo delle note lo tiene il driver")
except Exception as _e:
    import traceback
    print("patch 011 NON applicata: %s" % _e)
    traceback.print_exc()
